const params=new URLSearchParams(location.search);
let stored;try{stored=localStorage.getItem('sunnah-language')}catch{}
let lang=params.get('lang')==='en'?'en':params.get('lang')==='ar'?'ar':stored==='en'?'en':'ar';
try{localStorage.setItem('sunnah-language',lang)}catch{}
document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';
Object.assign(dict,{'زهرة عطرة':'Floral pink','ازرق':'Blue','ازرق سماوي':'Sky blue'});
const sorted=Object.keys(dict).sort((a,b)=>b.length-a.length);
function translate(value){if(!value)return value;if(dict[value])return dict[value];if(!/[\u0600-\u06ff]/.test(value))return value;let out=value;for(const key of sorted)out=out.split(key).join(dict[key]);return out;}
window.storeLanguage={lang,translate};
const reverse=Object.fromEntries(Object.entries(dict).map(([ar,en])=>[en,ar]));
const reverseKeys=Object.keys(reverse).sort((a,b)=>b.length-a.length);
const originals=new WeakMap();
const titleOriginal=document.title;
function untranslate(value){if(!value)return value;if(reverse[value])return reverse[value];let out=value;for(const key of reverseKeys)out=out.split(key).join(reverse[key]);return out;}
const attrs=['aria-label','placeholder','title','alt'];
function visit(root){if(root.nodeType===3){if(!root.parentElement?.closest('script,style,textarea,input,[data-language-switch]')){if(!originals.has(root))originals.set(root,lang==='en'?untranslate(root.nodeValue):root.nodeValue);const original=originals.get(root);const next=lang==='en'?translate(original):original;if(next!==root.nodeValue)root.nodeValue=next;}return;}if(root.nodeType!==1&&root.nodeType!==9)return;if(root.nodeType===1){if(root.matches('script,style,[data-language-switch]'))return;for(const attr of attrs){const v=root.getAttribute(attr);if(v){const next=lang==='en'?translate(v):untranslate(v);if(next!==v)root.setAttribute(attr,next);}}}for(const node of root.childNodes)visit(node);}
function init(){
const categories=document.querySelector('.category-links');
if(categories&&!categories.querySelector('[href*="category=5"]')){const a=document.createElement('a');a.href='shop.html?category=5';const image=document.createElement('img');image.src='/assets/products/SSBM0018-new-0.jpg';image.alt='';image.loading='lazy';const label=document.createElement('div');label.className='category-label';label.textContent='تشكيلة الشتاء';a.append(image,label);categories.append(a);}
const nav=document.querySelector('header nav');
if(nav&&!nav.querySelector('[data-language-switch]')){const link=document.createElement('a');link.dataset.languageSwitch='';const url=new URL(location.href);url.searchParams.set('lang',lang==='en'?'ar':'en');link.href=url.pathname+url.search;link.lang=lang==='en'?'ar':'en';link.textContent=lang==='en'?'العربية':'English';nav.append(link);}
visit(document.body);if(lang==='en')document.title=translate(document.title);
function switchLanguage(next){
lang=next;window.storeLanguage.lang=lang;
try{localStorage.setItem('sunnah-language',lang)}catch{}
document.documentElement.lang=lang;document.documentElement.dir=lang==='en'?'ltr':'rtl';
const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u.pathname+u.search+u.hash);
visit(document.body);
window.storeApplyLanguage?.(lang);
const link=nav?.querySelector('[data-language-switch]');if(link){link.textContent=lang==='en'?'العربية':'English';link.lang=lang==='en'?'ar':'en';u.searchParams.set('lang',lang==='en'?'ar':'en');link.href=u.pathname+u.search;}
for(const input of document.querySelectorAll('form[role=search] input[name=lang]'))input.value=lang;
document.title=lang==='en'?translate(untranslate(document.title)):untranslate(document.title);
}
nav?.querySelector('[data-language-switch]')?.addEventListener('click',event=>{event.preventDefault();switchLanguage(lang==='en'?'ar':'en');});
new MutationObserver(records=>{for(const r of records){if(r.type==='characterData')visit(r.target);else if(r.type==='attributes')visit(r.target);else for(const n of r.addedNodes)visit(n);}}).observe(document.body,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:attrs});
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(!a||a.hasAttribute('data-language-switch'))return;const u=new URL(a.href,location.href);if(u.origin===location.origin&&!u.pathname.startsWith('/editor')&&!u.pathname.startsWith('/admin')){u.searchParams.set('lang',lang);a.href=u.href;}},true);
for(const form of document.querySelectorAll('form[role=search]')){const hidden=document.createElement('input');hidden.type='hidden';hidden.name='lang';hidden.value=lang;form.append(hidden);}
}
